// Setup = one month of the value. Retainer = 10% of it. Floors so you never sell cheap.
const f = $input.first().json;
const hours = Number(f['Hours a month it saves them']) || 0;
const rate = Number(f['What an hour of their time costs ($)']) || 0;
const ai = /^y/i.test(String(f['Uses AI? (yes or no)'] || '').trim());
const round = (n, step) => Math.round(n / step) * step;

const value = Math.round(hours * rate);                               // what the task costs them a month
const setup = Math.max(ai ? 1500 : 500, round(value, 50));            // floor: $500 plain, $1,500 AI
const retainer = Math.max(ai ? 150 : 75, round(value * 0.10, 25));    // floor: $75 plain, $150 AI

const paybackMonths = Math.round(setup / Math.max(1, value - retainer) * 10) / 10;
const clientYearOne = value * 12 - setup - retainer * 11;             // retainer starts month two
const youYearOne = setup + retainer * 11;
const aiNote = ai ? 'AI model costs billed monthly at cost, on top.' : 'No AI costs.';
return [{ json: { business: f['Business name'], automation: f['Automation'], ai, value, setup, retainer, paybackMonths, clientYearOne, youYearOne, aiNote } }];
